styles.css:
@theme {
  --ref-action: #111111;
  --ref-analysis-emphasis: oklch(43% 0.08 70);
  --ref-analysis-positive: oklch(44% 0.105 185);
  --ref-four-player-sequence-1: #222222;
  --ref-rank-1: #333333;
  --ref-series-1: #444444;
  --ref-status-info: oklch(45% 0.115 285);
  --ref-status-success: #555555;
  --color-action: var(--ref-action);
  --color-analysis-emphasis: var(--ref-analysis-emphasis);
  --color-analysis-positive: var(--ref-analysis-positive);
  --color-member-sequence-1: var(--ref-four-player-sequence-1);
  --color-play-order-1: var(--ref-four-player-sequence-1);
  --color-rank-1: var(--ref-rank-1);
  --color-series-1: var(--ref-series-1);
  --color-status-info: var(--ref-status-info);
  --color-success: var(--ref-status-success);
}
